  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      airtableApiKey: 'test-api-key',
      airtableBaseId: 'appTestBase',
      airtableTableName: 'TestTable',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as ShopifyOrderPaidPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.airtableRecordId).toBe('recXXXXXXXXXXXX')
    expect(result.createdTime).toBe('2024-01-01T12:00:00.000Z')
  })
})

describe('handle', () => {
  it('maps fields correctly and calls Airtable with expected body', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) =>
      req.url.includes('/v0/appTestBase/TestTable') ? jsonResponse(TARGET_ENDPOINTS[0].response, 201) : jsonResponse({ error: 'not found' }, 404)
    )

    const config: ConnectorConfig = {
      airtableApiKey: 'test-api-key',
      airtableBaseId: 'appTestBase',
      airtableTableName: 'TestTable',
      fetch,
    }

    const payload: ShopifyOrderPaidPayload = {
      id: 987654321,
      email: 'test@example.com',
      total_price: '99.99',
    }

    const result = await handle(payload, config)

    expect(calls.length).toBe(1)
    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://api.airtable.com/v0/appTestBase/TestTable')
    expect(call.headers.get('authorization')).toBe('Bearer test-api-key')
    expect(call.json).toEqual({
      fields: {
        'Order ID': 987654321,
        Email: 'test@example.com',
        Total: '99.99',
      },
    })
    expect(result.airtableRecordId).toBe('recXXXXXXXXXXXX')
  })

  it('throws descriptive error when id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      airtableApiKey: 'test-api-key',
      airtableBaseId: 'appTestBase',
      airtableTableName: 'TestTable',
      fetch,
    }

    const payload = { email: 'test@example.com', total_price: '10.00' } as unknown as ShopifyOrderPaidPayload

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: id (number)')
  })

  it('throws descriptive error when email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      airtableApiKey: 'test-api-key',
      airtableBaseId: 'appTestBase',
      airtableTableName: 'TestTable',
      fetch,
    }

    const payload = { id: 123, total_price: '10.00' } as unknown as ShopifyOrderPaidPayload

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: email (string)')
  })

  it('throws descriptive error when total_price is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
