  it('throws error with status and endpoint on non-2xx response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const config: ConnectorConfig = {
      airtableApiKey: 'invalid-key',
      airtableBaseId: 'appTestBase',
      airtableTableName: 'TestTable',
      fetch,
    }

    const payload: ShopifyOrderPaidPayload = {
      id: 123,
      email: 'test@example.com',
      total_price: '10.00',
    }

    await expect(handle(payload, config)).rejects.toThrow('Airtable API error: 401 Unauthorized at POST https://api.airtable.com/v0/appTestBase/TestTable')
    expect(calls.length).toBe(1)
  })

  it('throws error on 500 response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Internal Server Error' }, 500))
    const config: ConnectorConfig = {
      airtableApiKey: 'test-api-key',
      airtableBaseId: 'appTestBase',
      airtableTableName: 'TestTable',
      fetch,
    }

    const payload: ShopifyOrderPaidPayload = {
      id: 123,
      email: 'test@example.com',
      total_price: '10.00',
